/** A project executor may be narrowed to the exact isolated workspace. */
export function autonomyWorkspaceAllowed(root:string,target:string){
 return absoluteExecutionPath(root)&&absoluteExecutionPath(target)&&executionPath(root)===executionPath(target)&&
  (executionPath(root).relative(root,target)===''||executionPathWithin(root,target));
}
const objective=z.object({id:identifier,title:z.string().min(1).max(1000),acceptance:z.array(z.string().min(1).max(8000)).min(1),dependsOn:z.array(identifier),workPackage:identifier,scope:identifier}).passthrough();
export const autonomySpecSchema=z.object({schemaVersion:z.literal(1),projectKey:identifier,version:identifier,workPackages:z.array(z.object({id:identifier,title:z.string().min(1).max(1000),dependsOn:z.array(identifier),budgetScope:identifier,objectiveIds:z.array(identifier).min(1)}).passthrough()).min(1).max(100),objectives:z.array(objective).min(1).max(1000)}).passthrough();
export const autonomyConfigSchema=z.object({machineId:identifier,workspace:z.string().min(1).max(2000),costPolicy:z.enum(['limited','record-only']).default('limited'),maxUSD:z.number().positive().max(10000).nullable(),maxTokens:z.number().int().positive().max(1000000000).nullable(),perTaskUSD:z.number().min(1).max(1000).nullable(),maxAttempts:z.number().int().min(1).max(20),maxRepeated:z.number().int().min(2).max(10).default(3),maxEvidenceAgeMs:z.number().int().min(60000).max(7*24*3600000).default(24*3600000),executors:z.record(identifier,z.object({worker:identifier,reviewer:identifier,validator:identifier.optional(),requiredCheckIds:z.array(identifier).min(1),budgetScope:identifier}).strict()),scopeBudgets:z.record(identifier,z.object({maxUSD:z.number().positive().nullable(),maxTokens:z.number().int().positive().nullable()}).strict())}).strict();
type Config=z.infer<typeof autonomyConfigSchema>;
type Spec=z.infer<typeof autonomySpecSchema>;
type Stage={id:string;status:string;attempt:number;taskId?:string;reviewTaskId?:string;runId?:string;reviewRunId?:string;validationTaskId?:string;validationRunId?:string;validationIntent?:CommandEnvelope;validationDispatchIntent?:CommandEnvelope;waiting?:any;waitingSince?:string;nextProbeAt?:string;probeCount?:number;workerIntent?:CommandEnvelope;reviewIntent?:CommandEnvelope;dispatchIntent?:CommandEnvelope;reviewDispatchIntent?:CommandEnvelope;decision?:any;problem?:string;checkpoint?:any;history:any[]};
type Profile={projectId:string;revision:number;status:string;reason:string|null;goalSpecHash:string;spec:Spec;config:Config;binding:string;templateHashes:Record<string,string>;stages:Stage[];createdAt:string;updatedAt:string};
