  if(!task||task.projectId!==id||task.machineId!==p.config.machineId||task.agent!==executor.worker||task.executionRequest?.id!==parsed.oldRunId||!['cancelled','paused','interrupted'].includes(task.status)||!run||run.taskId!==task.id||run.projectId!==id||run.machineId!==p.config.machineId||run.executorId!==executor.worker||run.workspace!==p.config.workspace)reject('实际旧执行的项目、机器或角色不匹配','RECOVERY_SCOPE_INVALID');
