   for(const [budget,maxUSD,maxTokens] of [[this.budget(p),p.config.maxUSD??0,p.config.maxTokens??0],[this.budget(p,executor.budgetScope),p.config.scopeBudgets[executor.budgetScope].maxUSD??0,p.config.scopeBudgets[executor.budgetScope].maxTokens??0]] as const){const decision=evaluateAutonomyBudget({...budget,maxUSD,maxTokens,nextBudgetUSD:p.config.perTaskUSD??0,nextTokenLimit:template.supervision?.maxTokens??1});if(decision.outcome==='stop')reject('原预算边界不允许新代：'+decision.reason,'RECOVERY_BUDGET_UNAVAILABLE');}
