 private preflight(p:Profile){if(this.options.stopped())reject('平台急停生效');const project=this.repository.read('projects',p.projectId,this.actor);if(!project||this.binding(project)!==p.binding)reject('项目目标或工作副本变化，需重新核对冻结计划');for(const [id,hash] of Object.entries(p.templateHashes)){const template=this.execution.templates().find(t=>t.id===id);if(!template||sha(template)!==hash)reject('冻结的执行器配置已变化');}const active=p.stages.find(s=>s.status!=='passed');if(active){const e=p.config.executors[active.id];if(['waiting-prerequisite','validating-prerequisite'].includes(active.status)?(!e.validator||!this.execution.ready(e.validator,p.config.machineId)):(!this.execution.ready(e.worker,p.config.machineId)||!this.execution.ready(e.reviewer,p.config.machineId)))reject('开发或评审节点暂未就绪','RESOURCE_UNAVAILABLE',503);}}
