  if(!s[intentKey]){s[intentKey]={commandId:randomUUID(),expectedVersion:0,scope:'personal',payload:{title:`${s.id} · ${validation?'固定复验':review?'独立评审':'开发修复'} ${s.attempt}`,projectId:p.projectId,machineId:p.config.machineId,agent:executorId,mode:'managed',goal:validation?'仅按冻结root验证器重新核验当前源码、产物和等待条件；禁止调用模型或将等待判为通过。':this.goal(p,s,review),criteria:'本阶段目标全部有当前同源真实证据；固定验证通过及独立逐目标评审后方可通过。',budget:p.config.perTaskUSD??1,retryLimit:0,worktree:p.config.workspace}};this.persist(p,'task-intent',{workPackage:s.id,attempt:s.attempt,review,commandId:s[intentKey]!.commandId});}
